JOIN centros c ON c.codigo_centro = v.codigo_centro
JOIN programas p ON p.codigo_programa = v.codigo_programa
ON CONFLICT (ficha_caracterizacion) DO UPDATE
SET estado_ficha = EXCLUDED.estado_ficha,
    fecha_inicial = EXCLUDED.fecha_inicial,
    fecha_final = EXCLUDED.fecha_final,
    centro_id = EXCLUDED.centro_id,
    programa_id = EXCLUDED.programa_id;

SELECT setval('fichas_id_seq', (SELECT MAX(id) FROM fichas));

